/// <summary>
/// 房间配置 — 定义某一类房间的通用参数 + 多个可选预制体变体
/// </summary>
[CreateAssetMenu(fileName = "RoomConfig", menuName = "Map/Room Config")]
public class RoomConfig : ScriptableObject
{
    [Header("基础信息")]
    [Tooltip("房间类型")]
    public RoomType roomType;

    [Tooltip("可选房间预制体列表 (生成时随机选取一个)")]
    public GameObject[] roomPrefabs;

    [Tooltip("难度等级 (影响怪物属性缩放等)")]
    public int difficultyLevel = 1;

    [Header("连接点 — 该房间有哪些方向的门")]
    public bool hasTopDoor;
    public bool hasBottomDoor;
    public bool hasLeftDoor;
    public bool hasRightDoor;

    [Header("房间尺寸 (世界单位，用于摄像机边界和布局计算)")]
    public Vector2 roomSize = new Vector2(20f, 12f);

    [Header("门在房间内的本地坐标偏移")]
    public Vector2 topDoorOffset = new Vector2(0f, 6.5f);
    public Vector2 bottomDoorOffset = new Vector2(0f, -6.5f);
    public Vector2 leftDoorOffset = new Vector2(-10.5f, 0f);
    public Vector2 rightDoorOffset = new Vector2(10.5f, 0f);

    [Header("怪物生成")]
    [Tooltip("可选怪物池")]
    public List<EnemySpawnEntry> enemyPool = new();

    [Tooltip("最少生成怪物数")]
    public int minEnemies = 1;

    [Tooltip("最多生成怪物数")]
    public int maxEnemies = 3;

    [Header("道具生成")]
    [Tooltip("可选道具池")]
    public List<GameObject> itemPool = new();

    [Tooltip("最少道具数")]
    public int minItems = 0;

    [Tooltip("最多道具数")]
    public int maxItems = 2;

    [Header("隐藏墙")]
    [Tooltip("隐藏墙血量 (需要攻击次数)，0=普通门")]
    public int hiddenWallHP = 0;

    /// <summary>获取指定方向门的本地坐标偏移</summary>
    public Vector2 GetDoorOffset(DoorDirection dir)
    {
        return dir switch
        {
            DoorDirection.Top => topDoorOffset,
            DoorDirection.Bottom => bottomDoorOffset,
            DoorDirection.Left => leftDoorOffset,
            DoorDirection.Right => rightDoorOffset,
            _ => Vector2.zero
        };
    }

    /// <summary>检查是否有指定方向的门</summary>
    public bool HasDoor(DoorDirection dir)
    {
        return dir switch
        {
            DoorDirection.Top => hasTopDoor,
            DoorDirection.Bottom => hasBottomDoor,
            DoorDirection.Left => hasLeftDoor,
            DoorDirection.Right => hasRightDoor,
            _ => false
        };
    }

    /// <summary>获取门的相反方向</summary>
    public static DoorDirection OppositeDir(DoorDirection dir)
    {
        return dir switch
        {
            DoorDirection.Top => DoorDirection.Bottom,
            DoorDirection.Bottom => DoorDirection.Top,
            DoorDirection.Left => DoorDirection.Right,
            DoorDirection.Right => DoorDirection.Left,
            _ => DoorDirection.Top
        };
    }

    /// <summary>从预制体池中随机选取一个。池为空时返回 null。</summary>
    public GameObject GetRandomPrefab()
    {
        if (roomPrefabs == null || roomPrefabs.Length == 0) return null;
        return roomPrefabs[Random.Range(0, roomPrefabs.Length)];
    }
}

using UnityEngine;

/// <summary>
/// 道具 UI Controller —— 监听 ItemManager（Model），通知 ItemPanel（View）。
/// 本类是 Model ↔ View 的唯一耦合点。
/// 沿用 SkillUIController 的模式。
/// </summary>
public class ItemUIController : MonoBehaviour
{
    [Header("Model 引用")]
    [SerializeField] private ItemManager _itemManager;

    [Header("View 引用")]
    [SerializeField] private ItemPanel _panel;

    [Header("初始容量")]
    [SerializeField] private int _initialSlotCount = 16;

    // ==================== 生命周期 ====================

    private void Start()
    {
        // 跨场景后序列化引用失效，动态查找 ItemManager
        if (_itemManager == null)
            _itemManager = ResolveItemManager();

        if (_itemManager == null)
        {
            Debug.LogError("ItemUIController: ItemManager 未赋值", this);
            return;
        }
        if (_panel == null)
        {
            Debug.LogError("ItemUIController: ItemPanel 未赋值", this);
            return;
        }

        _panel.Initialize(_initialSlotCount);

        // 订阅 Model 事件
        _itemManager.OnItemAcquired += HandleItemAcquired;
        _itemManager.OnItemRemoved += HandleItemRemoved;

        // 初始全量刷新（已有道具）
        SyncAll();
    }

    private void OnDestroy()
    {
        if (_itemManager != null)
        {
            _itemManager.OnItemAcquired -= HandleItemAcquired;
            _itemManager.OnItemRemoved -= HandleItemRemoved;
        }
    }

    // ==================== Model 事件回调 ====================

    private void HandleItemAcquired(ItemData item)
    {
        // 在整个 Items 列表中查找新道具的索引
        int index = _itemManager.Items.Count - 1;
        SyncSlot(index, item, isNew: true);
    }

    private void HandleItemRemoved(ItemData item)
    {
        // 道具移除后全量同步（因为索引会变化）
        SyncAll();
    }

    // ==================== 核心同步 ====================

    /// <summary>全量同步所有道具</summary>
    private void SyncAll()
    {
        var items = _itemManager.Items;
        for (int i = 0; i < items.Count; i++)
            SyncSlot(i, items[i], isNew: false);
    }

    private void SyncSlot(int index, ItemData item, bool isNew)
    {
        ItemViewData data = new ItemViewData
        {
            Icon = item.icon,
            Name = item.itemName,
            Description = item.description,
            Quality = item.quality,
            IsNew = isNew
        };
        _panel.RefreshSlot(index, data);
    }

    // ==================== 查找 ====================

    /// <summary>运行时动态查找 ItemManager (解决跨场景序列化引用失效问题)</summary>
    private static ItemManager ResolveItemManager()
    {
        // 优先从 PlayerManager 获取持久化 Player
        if (PlayerManager.Instance != null && PlayerManager.Instance.CurrentPlayer != null)
            return PlayerManager.Instance.CurrentPlayer.GetComponent<ItemManager>();

        // 兜底: Tag 查找
        var player = GameObject.FindGameObjectWithTag("Player");
        return player != null ? player.GetComponent<ItemManager>() : null;
    }
}

using UnityEngine;

/// <summary>
/// 道具 UI 面板 —— 管理 ItemSlotView 的创建与刷新。
/// 类似 SkillUIPanel 的职责。
/// </summary>
public class ItemPanel : MonoBehaviour
{
    [Header("预制体与容器")]
    [SerializeField] private ItemSlotView _slotPrefab;
    [SerializeField] private Transform _container;

    /// <summary>最大显示槽位数</summary>
    [SerializeField] private int _maxSlots = 30;

    private ItemSlotView[] _views = System.Array.Empty<ItemSlotView>();

    /// <summary>Controller 调用，按数量创建槽位 View</summary>
    public void Initialize(int slotCount)
    {
        int count = Mathf.Min(slotCount, _maxSlots);

        // 清理旧子对象
        for (int i = _container.childCount - 1; i >= 0; i--)
            SafeDestroy(_container.GetChild(i).gameObject);

        _views = new ItemSlotView[count];
        for (int i = 0; i < count; i++)
        {
            ItemSlotView view = Instantiate(_slotPrefab, _container);
            view.name = $"ItemSlot_{i}";
            view.SetEmpty();
            _views[i] = view;
        }
    }

    /// <summary>Controller 调用，刷新指定槽位</summary>
    public void RefreshSlot(int index, in ItemViewData data)
    {
        if (index < 0 || index >= _views.Length)
        {
            // 自动扩容
            ExpandSlots(index + 1);
        }

        if (index >= 0 && index < _views.Length)
            _views[index]?.Refresh(data);
    }

    /// <summary>Controller 调用，将指定槽位设为空</summary>
    public void ClearSlot(int index)
    {
        if (index < 0 || index >= _views.Length) return;
        _views[index]?.SetEmpty();
    }

    /// <summary>获取指定槽位 View</summary>
    public ItemSlotView GetSlotView(int index)
    {
        if (index < 0 || index >= _views.Length) return null;
        return _views[index];
    }

    /// <summary>扩容槽位</summary>
    private void ExpandSlots(int newSize)
    {
        int target = Mathf.Min(newSize, _maxSlots);
        if (target <= _views.Length) return;

        var newViews = new ItemSlotView[target];
        for (int i = 0; i < _views.Length; i++)
            newViews[i] = _views[i];

        for (int i = _views.Length; i < target; i++)
        {
            ItemSlotView view = Instantiate(_slotPrefab, _container);
            view.name = $"ItemSlot_{i}";
            view.SetEmpty();
            newViews[i] = view;
        }

        _views = newViews;
    }

    private static void SafeDestroy(Object obj)
    {
        if (obj == null) return;
        if (Application.isPlaying)
            Destroy(obj);
        else
            DestroyImmediate(obj);
    }
}

